## install.packages("qgcomp")
## install.packages("Amelia")
library(mice)
library(survival)
library(forcats)
library(broom)
library(cmprsk)
library(miceadds)

## devtools::install_github("alexpkeil1/qgcomp")

load("/extra/home/hi97/R/registry/nj_res_hx/long_list_imp.Rda")
names(long_imp_list[[1]])

summary(long_imp_list[[1]]$pfoa)
summary(long_imp_list[[1]]$pfoa_dx) ## same

#####################################################################
# Combined with RR
#####################################################################


Xnm <- c('pfoa_dx','pfos_dx',
         'pfna_dx')

covars = c('age_cat.f', 'dxyr_cat.f','nhrace','nses_quin','insur.f',
           'married.f','stage.f','ndvi27_final','pm25_new','psa.f','txsurg.f',
           'txrad.f',"no2_new")


results <- lapply(long_imp_list, function(imp) {
  imp <- imp %>%
    dplyr::select(all_of(c(Xnm, covars, 'tstart', 'tstop', "cvd_death")))
  
  fit <- qgcomp.cox.noboot(
    survival::Surv(tstart, tstop, cvd_death) ~ .,
    expnms = Xnm,
    dat = imp,
    q = 5
  )
  
  c(psi = fit$psi,
    ci_ll = fit$ci[1],
    ci_ul = fit$ci[2],
    var = fit$var.psi)
})

results_df <- do.call(rbind, results) %>% as.data.frame()

m <- nrow(results_df)

psi_bar <- mean(results_df$psi)
within_var <- mean(results_df$var)
between_var <- var(results_df$psi)
total_var <- within_var + (1 + 1/m) * between_var
se_total <- sqrt(total_var)

# 95% CI using t-distribution with df = m - 1
df <- m - 1
tcrit <- qt(0.975, df)
ci_lower <- psi_bar - tcrit * se_total
ci_upper <- psi_bar + tcrit * se_total

rubin_result <- data.frame(
  psi = psi_bar,
  ci_ll = ci_lower,
  ci_ul = ci_upper
)
print(exp(rubin_result))


qc.fit <- qgcomp.cox.noboot(survival::Surv(tstart, tstop, cvd_death) ~.,expnms=Xnm, dat=long_imp_list[[1]][,c(Xnm, covars, 'tstart','tstop',"cvd_death")], q=5)

qc.fit
plot(qc.fit)